<?php require ROOT.'/app/Views/admin/nav.php'; ?><div class="page-heading"><h1>Gerenciar avisos</h1></div><form class="surface form-stack" action="<?= e(url('/admin/avisos')) ?>" method="post"><?= csrf() ?><?php foreach (['titulo'=>'Título','fonte'=>'Nome da fonte','url_fonte'=>'Endereço da fonte'] as $key=>$label): ?><div><label class="form-label" for="<?= e($key) ?>"><?= e($label) ?></label><input class="form-control" id="<?= e($key) ?>" name="<?= e($key) ?>" <?= $key==='url_fonte'?'type="url"':'' ?> required maxlength="<?= $key==='url_fonte'?500:160 ?>"></div><?php endforeach ?><label for="descricao">Descrição</label><textarea class="form-control" id="descricao" name="descricao" minlength="10" maxlength="3000" required></textarea><button class="btn btn-primary align-self-start">Publicar aviso</button></form>
<?php foreach ($rows as $r): ?><section class="surface mt-3"><h2 class="h5"><?= e($r['titulo']) ?></h2><p><?= e($r['status']) ?></p><?php if ($r['status']==='PUBLICADO'): ?><form method="post" action="<?= e(url('/admin/avisos')) ?>"><?= csrf() ?><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><button class="btn btn-outline-secondary">Arquivar</button></form><?php endif ?></section><?php endforeach ?>
